package com.focusflow.api.security; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; @Service public class JwtService { private final SecretKey key; public JwtService(@Value("${app.jwt-secret}") String secret){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String create(String id,String email){return Jwts.builder().subject(id).claim("email",email).issuedAt(new Date()).expiration(Date.from(Instant.now().plus(Duration.ofDays(7)))).signWith(key).compact();} public String userId(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} }
